<?php require 'includes/bootstrap.php';require_role('admin');$rows=$pdo->query("SELECT * FROM student WHERE is_approved=0 ORDER BY id DESC")->fetchAll();page_start('Student Requests');?><div class="vc-card"><h2>Student Approval Requests</h2><form method="post" action="admin_approve.php"><input type="hidden" name="kind" value="student"><table class="table table-striped"><thead><tr><th>Select</th><th>Name</th><th>Roll No</th><th>Email</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><input type="checkbox" name="ids[]" value="<?=e($r['id'])?>"></td><td><?=e($r['name'])?></td><td><?=e($r['roll_no'])?></td><td><?=e($r['email'])?></td></tr><?php endforeach;?></tbody></table><button class="btn btn-success" name="action" value="approve">Approve selected</button> <button class="btn btn-danger" name="action" value="reject">Reject selected</button></form></div><?php page_end();?>